DROP TABLE IF EXISTS `CourseAnnouncements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `CourseAnnouncements` (
  `AnnouncementID` int NOT NULL AUTO_INCREMENT,
  `CRN` int NOT NULL,
  `FacultyID` int unsigned NOT NULL,
  `Title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `Message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `DatePosted` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`AnnouncementID`),
  KEY `fk_CourseAnnouncements_CourseSection` (`CRN`),
  KEY `fk_CourseAnnouncements_Faculty` (`FacultyID`),
  CONSTRAINT `fk_CourseAnnouncements_CRN` FOREIGN KEY (`CRN`) REFERENCES `CourseSection` (`CRN`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseAnnouncements_FacultyID` FOREIGN KEY (`FacultyID`) REFERENCES `Faculty` (`FacultyID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
