--
-- Table structure for table `CourseSection`
--

DROP TABLE IF EXISTS `CourseSection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `CourseSection` (
  `CRN` int NOT NULL AUTO_INCREMENT,
  `CourseID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `CourseSectionNo` int NOT NULL,
  `FacultyID` int unsigned DEFAULT NULL,
  `TimeSlotID` int DEFAULT NULL,
  `RoomID` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Year` int DEFAULT NULL,
  `SemesterID` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `AvailableSeats` int DEFAULT NULL,
  `Status` enum('PLANNED','IN-PROGRESS','COMPLETED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`CRN`),
  KEY `idx_section_course` (`CourseID`),
  KEY `idx_section_faculty` (`FacultyID`),
  KEY `idx_section_timeslot` (`TimeSlotID`),
  KEY `idx_section_room` (`RoomID`),
  KEY `idx_section_semester` (`SemesterID`),
  CONSTRAINT `fk_CourseSection_CourseID` FOREIGN KEY (`CourseID`) REFERENCES `Course` (`CourseID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSection_FacultyID` FOREIGN KEY (`FacultyID`) REFERENCES `Faculty` (`FacultyID`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSection_RoomID` FOREIGN KEY (`RoomID`) REFERENCES `Room` (`RoomID`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSection_SemesterID` FOREIGN KEY (`SemesterID`) REFERENCES `Semester` (`SemesterID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSection_TimeSlotID` FOREIGN KEY (`TimeSlotID`) REFERENCES `TimeSlot` (`TS_ID`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5687 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

