CREATE TABLE `CourseSectionAttendance` (
  `StudentID` int unsigned NOT NULL,
  `CRN` int NOT NULL,
  `CourseID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `AttendanceDate` date NOT NULL,
  `PresentAbsent` enum('PRESENT','ABSENT') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`StudentID`,`CRN`,`AttendanceDate`),
  KEY `fk_CSA_CourseSection` (`CRN`),
  KEY `fk_CSA_Course` (`CourseID`),
  CONSTRAINT `fk_CourseSectionAttendance_CourseID` FOREIGN KEY (`CourseID`) REFERENCES `Course` (`CourseID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSectionAttendance_CRN` FOREIGN KEY (`CRN`) REFERENCES `CourseSection` (`CRN`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_CourseSectionAttendance_StudentID` FOREIGN KEY (`StudentID`) REFERENCES `Student` (`StudentID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
