--
-- Table structure for table `FacultyHistory`
--

DROP TABLE IF EXISTS `FacultyHistory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `FacultyHistory` (
  `CRN` int NOT NULL,
  `FacultyID` int unsigned DEFAULT NULL,
  `CourseID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `SemesterID` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `FacultyHistoryID` int NOT NULL,
  `Year` int DEFAULT NULL,
  `AssignedDate` datetime DEFAULT NULL,
  `Status` enum('ACTIVE','INACTIVE') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ACTIVE',
  `DeptID` int DEFAULT NULL,
  `HistoryID` int unsigned NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`HistoryID`),
  KEY `idx_fachist_faculty` (`FacultyID`),
  KEY `idx_fachist_course` (`CourseID`),
  KEY `idx_fachist_semester` (`SemesterID`),
  KEY `fk_FacHistory_CourseSection` (`CRN`),
  KEY `fk_FacHistory_Dept` (`DeptID`),
