--
-- Table structure for table `StudentEnrollment`
--

DROP TABLE IF EXISTS `StudentEnrollment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `StudentEnrollment` (
  `StudentID` int unsigned NOT NULL,
  `SemesterID` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `CRN` int NOT NULL,
  `CourseID` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `Status` enum('COMPLETED','ENROLLED','DROPPED','IN-PROGRESS','WAITLIST','PLANNED') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `EnrollmentDate` date NOT NULL,
  `Grade` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`StudentID`,`SemesterID`,`CRN`),
  KEY `idx_enroll_student` (`StudentID`),
  KEY `idx_enroll_crn` (`CRN`),
  KEY `idx_enroll_course` (`CourseID`),
  KEY `idx_enroll_semester` (`SemesterID`),
  CONSTRAINT `fk_StudentEnrollment_CourseID` FOREIGN KEY (`CourseID`) REFERENCES `Course` (`CourseID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_StudentEnrollment_CRN` FOREIGN KEY (`CRN`) REFERENCES `CourseSection` (`CRN`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_StudentEnrollment_SemesterID` FOREIGN KEY (`SemesterID`) REFERENCES `Semester` (`SemesterID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_StudentEnrollment_StudentID` FOREIGN KEY (`StudentID`) REFERENCES `Student` (`StudentID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

